export const STRIDE=6;const p=540;let s=[],t=null,i=0,u=0;export function startRecording(r){return s=r.map(e=>e.settings.position),s.includes("ball")||s.push("ball"),t=new Float32Array(s.length*6*540),i=0,u=0,s.slice()}function d(){if((i+1)*s.length*6<=t.length)return;const e=new Float32Array(t.length*2);e.set(t),t=e}export function record(r){if(!t)return;d();const e=i*s.length*6;t.fill(0,e,e+s.length*6);for(const n of r){const c=s.indexOf(n.settings.position);if(c===-1)continue;const o=e+c*6;t[o]=n.coords.x,t[o+1]=n.coords.y,t[o+2]=n.coords.z||0,t[o+3]=n.state&&n.state.xSpeed||0,t[o+4]=n.state&&n.state.ySpeed||0,t[o+5]=n.settings.benched?0:1}i+=1}export function frameCount(){return i}export function slotNames(){return s.slice()}export function frameAt(r,e){if(!t||i===0)return[];const c=Math.max(0,Math.min(i-1,Math.floor(r)))*s.length*6,o=[];for(let a=0;a<s.length;a+=1){const l=c+a*6,f=s[a];o.push({settings:{position:f,team:e?e(f):0,benched:t[l+5]===0},coords:{x:t[l],y:t[l+1],z:t[l+2]},state:{xSpeed:t[l+3],ySpeed:t[l+4]}})}return o}export function focusAt(r){const e=frameAt(r),n=e.find(o=>o.settings.position==="ball"&&!o.settings.benched);if(n&&(n.coords.x||n.coords.y))return n.coords;const c=e.find(o=>o.settings.position==="qb");return c?c.coords:{x:0,y:0,z:0}}export function rewind(){u=0}export function advance(r,e,n=1){return u+=r*e*n,u>=i}export function playheadFrame(){return u}export function isEmpty(){return i===0}export function discard(){t=null,s=[],i=0,u=0}
